@startuml

class Property {
  + alphanumericCode : string
  + address : string
  + zipCode : string
  + city : string
  + area : int
  + ToString() : string
  + Contains(key: string) : boolean
  + Write() : void
}

class Garage extends Property {
  + numberOfParkingSpaces : int
}

class Apartment extends Property {
  + numberOfRooms : int
  + numberOfBathrooms : int
}

class Villa extends Apartment {
  + gardenSize : int
}

@enduml

